import type { SupabaseClient } from "@supabase/supabase-js";
import { supabase } from "@/integrations/supabase/client";

const url = import.meta.env.VITE_SUPABASE_URL;
const key = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY ?? import.meta.env.VITE_SUPABASE_ANON_KEY;
// Reuse Lovable's client, including its Cloud fetch adapter and preview auth storage.
// Gallery table types are generated by Lovable when the migration is applied.
export const galleryClient = url && key ? (supabase as SupabaseClient) : null;
export const PHOTO_BUCKET = "gallery-previews";
export const CHECKOUT_URL = "https://privacy.com.br/checkout/casaldemaringa";

export type GalleryPhoto = {
  id: string;
  title: string;
  storage_path: string;
  created_at: string;
};

export async function listPhotos(): Promise<GalleryPhoto[]> {
  if (!galleryClient) return [];
  const { data, error } = await galleryClient
    .from("gallery_photos")
    .select("id, title, storage_path, created_at")
    .order("created_at", { ascending: false });
  if (error) throw error;
  return data ?? [];
}

export function photoUrl(path: string) {
  return galleryClient?.storage.from(PHOTO_BUCKET).getPublicUrl(path).data.publicUrl ?? "";
}
